/** Latest spec per model (most recent year), keyed by lower-cased model name. */
export const INDIA_CATALOG_BY_MODEL: Record<string, Partial<Vehicle>> = (() => {
  const m: Record<string, Partial<Vehicle>> = {}
  for (const v of INDIA_CATALOG) {
    const k = (v.model ?? '').toLowerCase()
    if (!k) continue
    const prev = m[k]
    if (!prev || (v.year ?? 0) >= (prev.year ?? 0)) m[k] = v
  }
  return m
})()

export const INDIA_MODELS: string[] = [...new Set(INDIA_CATALOG.map((v) => v.model!).filter(Boolean))].sort()
